package dev.odin.controls;
import android.content.*;import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
/** AYN privileged window renderer. No profile, settings or shell writes here.
 * All user actions return to the regular app service for validation/execution. */
public final class RootTilePopup {
 private static File folder;private static WindowManager wm;private static View panel;private static Handler handler;private static Context context;private static int parent;private static long touched,blockedUntil;private static boolean closing,refreshing,busy;private static String last="";private static final ArrayList<RadioButton> radios=new ArrayList<>();private static final ArrayList<String> names=new ArrayList<>();private static Switch analog,side;private static Button on,off;
 public static void main(String[] args){try{
  if(android.os.Process.myUid()!=0||!TilePopupService.supported(Build.MODEL,Build.VERSION.SDK_INT))throw new SecurityException("Unsupported privileged chooser");
  folder=new File(args[0]);parent=Integer.parseInt(args[1]);if(!folder.getCanonicalPath().startsWith("/storage/emulated/0/Android/data/dev.odin.controls/files/tile-popup-")&&!folder.getCanonicalPath().startsWith("/sdcard/Android/data/dev.odin.controls/files/tile-popup-"))throw new SecurityException("Invalid chooser location");
  Looper.prepareMainLooper();android.graphics.Typeface.class.getMethod("loadPreinstalledSystemFontMap").invoke(null);Class<?> at=Class.forName("android.app.ActivityThread");Object thread=at.getMethod("systemMain").invoke(null);Context system=(Context)at.getMethod("getSystemContext").invoke(thread);android.hardware.display.DisplayManager dm=(android.hardware.display.DisplayManager)system.getSystemService(Context.DISPLAY_SERVICE);context=system.createDisplayContext(dm.getDisplay(0)).createWindowContext(2017,null);JSONObject config=read();if(SystemClock.uptimeMillis()-config.optLong("heartbeat",0)*1000>5000)throw new IOException("Chooser bridge is no longer active");boolean light=config.getBoolean("light");context=new ContextThemeWrapper(context,light?android.R.style.Theme_Material_Light:android.R.style.Theme_Material){@Override public Object getSystemService(String name){if(name.equals("autofill")||name.equals("content_capture"))return null;return super.getSystemService(name);}};wm=(WindowManager)context.getSystemService(Context.WINDOW_SERVICE);handler=new Handler(Looper.getMainLooper());
  LinearLayout content=new LinearLayout(context){
   @Override protected void onMeasure(int widthSpec,int heightSpec){int max=context.getResources().getDisplayMetrics().heightPixels-dp(64);int available=MeasureSpec.getMode(heightSpec)==MeasureSpec.UNSPECIFIED?max:Math.min(max,MeasureSpec.getSize(heightSpec));super.onMeasure(widthSpec,MeasureSpec.makeMeasureSpec(available,MeasureSpec.AT_MOST));}
   @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getKeyCode()==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)close();return true;}return super.dispatchKeyEvent(event);}
   @Override public boolean dispatchTouchEvent(MotionEvent e){touched=SystemClock.uptimeMillis();if(e.getAction()==MotionEvent.ACTION_OUTSIDE||(e.getAction()==MotionEvent.ACTION_DOWN&&(e.getX()<0||e.getY()<0||e.getX()>getWidth()||e.getY()>getHeight()))){close();return true;}return super.dispatchTouchEvent(e);}
  };content.setOrientation(1);content.setPadding(dp(24),dp(16),dp(24),dp(8));content.setBackgroundColor(light?0xffFFFFFF:0xff303034);
  TextView title=new TextView(context);title.setText(config.getBoolean("fan")?"Raven Fan":"Raven LED");title.setTextSize(20);title.setTextColor(light?0xff202124:0xffF2F2F2);content.addView(title,new LinearLayout.LayoutParams(-1,dp(48)));
  LinearLayout profileList=new LinearLayout(context);profileList.setOrientation(1);
  JSONArray list=config.getJSONArray("names");for(int n=0;n<list.length();n++){final String name=list.getString(n);names.add(name);RadioButton radio=new RadioButton(context);radio.setText(name);radio.setTextColor(light?0xff202124:0xffF2F2F2);radio.setTextSize(16);radio.setButtonTintList(tint(config));radio.setOnClickListener(v->{if(!busy)send("profile",name,false,false);});radios.add(radio);profileList.addView(radio,new LinearLayout.LayoutParams(-1,dp(48)));}
  ScrollView profiles=new ScrollView(context);profiles.setContentDescription("Profile list");profiles.addView(profileList);content.addView(profiles,new LinearLayout.LayoutParams(-1,0,1));
  if(!config.getBoolean("fan")&&config.optBoolean("separateGroups")){analog=toggle("Analog lights",true,config);side=toggle("Side lights",false,config);content.addView(analog,new LinearLayout.LayoutParams(-1,dp(48)));content.addView(side,new LinearLayout.LayoutParams(-1,dp(48)));}
  LinearLayout buttons=new LinearLayout(context);off=button("Turn off",false,config);on=button("Turn on",true,config);buttons.addView(off,new LinearLayout.LayoutParams(0,dp(48),1));buttons.addView(on,new LinearLayout.LayoutParams(0,dp(48),1));content.addView(buttons);
  panel=content;
  WindowManager.LayoutParams lp=new WindowManager.LayoutParams(Math.min(dp(400),context.getResources().getDisplayMetrics().widthPixels-dp(32)),-2,2017,WindowManager.LayoutParams.FLAG_DIM_BEHIND|WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.CENTER;lp.dimAmount=0.4f;lp.setTitle(config.getBoolean("fan")?"Raven Fan":"Raven LED");wm.addView(panel,lp);panel.post(()->{try{android.window.OnBackInvokedDispatcher back=panel.findOnBackInvokedDispatcher();if(back!=null)back.registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,RootTilePopup::close);}catch(Exception e){android.util.Log.w("RavenPopup","Using key-event Back handling",e);}});panel.setFocusableInTouchMode(true);panel.requestFocus();touched=SystemClock.uptimeMillis();update(config);try(FileOutputStream out=new FileOutputStream(new File(folder,"ready"))){out.write(1);}handler.post(tick);Looper.loop();
 }catch(Throwable e){e.printStackTrace();close();}}
 private static int ink(JSONObject j){return AppearanceColors.readable(j.optInt("accent",0xffff8000),j.optBoolean("light")?0xffFFFFFF:0xff303034);}
 private static int dp(int n){return Math.round(n*context.getResources().getDisplayMetrics().density);}
 private static android.content.res.ColorStateList tint(JSONObject j){return new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{j.optInt("accent",0xffff8000),0xff999999});}
 private static Switch toggle(String label,boolean a,JSONObject j){Switch s=new Switch(context);s.setText(label);s.setContentDescription(label);s.setTextSize(16);s.setTextColor(j.optBoolean("light")?0xff202124:0xffF2F2F2);s.setThumbTintList(tint(j));s.setTrackTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{(j.optInt("accent",0xffff8000)&0xffffff)|0x66000000,0x66999999}));s.setOnCheckedChangeListener((v,checked)->{if(!refreshing&&!busy)send("group",null,checked,a);});return s;}
 private static Button button(String label,boolean enabled,JSONObject j){Button b=new Button(context);b.setText(label);b.setTextColor(AppearanceColors.readable(j.optInt("accent",0xffff8000),j.optBoolean("light")?0xffFFFFFF:0xff303034));b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->{if(!busy)send("power",null,enabled,false);});return b;}
 private static JSONObject read()throws Exception{File f=new File(folder,"config.json");try(FileInputStream in=new FileInputStream(f)){byte[] bytes=new byte[(int)f.length()];int n=0,r;while(n<bytes.length&&(r=in.read(bytes,n,bytes.length-n))>0)n+=r;return new JSONObject(new String(bytes,0,n,"UTF-8"));}}
 private static void update(JSONObject j){refreshing=true;busy=j.optBoolean("busy")||SystemClock.uptimeMillis()<blockedUntil;for(int n=0;n<radios.size();n++){radios.get(n).setChecked(names.get(n).equals(j.optString("active")));radios.get(n).setEnabled(!busy);}if(analog!=null){analog.setChecked(j.optBoolean("analog"));side.setChecked(j.optBoolean("side"));analog.setEnabled(!busy);side.setEnabled(!busy);}on.setEnabled(!busy);off.setEnabled(!busy);refreshing=false;}
 private static final Runnable tick=new Runnable(){public void run(){if(closing)return;try{if(!new File("/proc/"+parent).exists()||!context.getSystemService(PowerManager.class).isInteractive()||context.getSystemService(KeyguardManager.class).isKeyguardLocked()||SystemClock.uptimeMillis()-touched>180000){close();return;}JSONObject j=read();if(SystemClock.uptimeMillis()-j.optLong("heartbeat",0)*1000>5000){close();return;}String s=j.toString();update(j);last=s;}catch(Exception e){e.printStackTrace();close();return;}handler.postDelayed(this,250);}};
 private static void send(String action,String name,boolean enabled,boolean a){try{touched=SystemClock.uptimeMillis();JSONObject j=new JSONObject().put("action",action).put("enabled",enabled).put("analog",a);if(name!=null)j.put("name",name);try(FileOutputStream out=new FileOutputStream(new File(folder,"events"),true)){out.write((j.toString()+"\n").getBytes("UTF-8"));}if(!action.equals("close")){blockedUntil=SystemClock.uptimeMillis()+750;busy=true;on.setEnabled(false);off.setEnabled(false);for(RadioButton r:radios)r.setEnabled(false);if(analog!=null){analog.setEnabled(false);side.setEnabled(false);}last="";}}catch(Exception e){e.printStackTrace();close();}}
 private static void close(){if(closing)return;closing=true;if(folder!=null)send("close",null,false,false);if(wm!=null&&panel!=null)try{wm.removeViewImmediate(panel);}catch(Exception ignored){}System.exit(0);}
}
